.dashboard {
  display: grid;
  grid-template-areas:
    "header header header"
    "sidebar main main"
    "sidebar widgets widgets"
    "footer footer footer";
  grid-template-columns: 200px repeat(2, minmax(200px, 1fr));
  grid-template-rows: auto 1fr 1fr auto;
  gap: 1rem;
  min-height: 100vh;
}

.header {
  grid-area: header;
  background: #2c3e50;
  color: white;
  padding: 1rem;
}

.sidebar {
  grid-area: sidebar;
  grid-row: span 2;
  background: #34495e;
  color: white;
  padding: 1rem;
}

.main-content {
  grid-area: main;
  background: #ecf0f1;
  padding: 1rem;
}

.widgets {
  grid-area: widgets;
  background: #bdc3c7;
  padding: 1rem;
}

.footer {
  grid-area: footer;
  background: #2c3e50;
  color: white;
  padding: 1rem;
  text-align: center;
}
